Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAX_M = 2000015;
const int MAX_N = 5775;

int n, m, c, d, k;

int read() {
    int x = 0, f = 1;
    char c = getchar();
    while (c < '0' || c > '9') { if (c == '-') f = -1; c = getchar(); }
    while (c >= '0' && c <= '9') { x = x * 10 + c - '0'; c = getchar(); }
    return x * f;
}

struct Edge {
    int to, next, cap, flow, cost;
} e[MAX_M];

int h[MAX_N], ec;
int pre[MAX_N], dis[MAX_N];
bool inq[MAX_N];
int N;

void init(int nodes) {
    N = nodes;
    ec = 0;
    memset(h, -1, sizeof(h));
}

void link(int u, int v, int cap, int cost) {
    e[ec] = {v, h[u], cap, 0, cost};
    h[u] = ec++;
    e[ec] = {u, h[v], 0, 0, -cost};
    h[v] = ec++;
}

bool spfa(int s, int t) {
    queue<int> q;
    fill(dis, dis + N, INF);
    fill(inq, inq + N, false);
    fill(pre, pre + N, -1);
    dis[s] = 0;
    inq[s] = true;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = false;
        for (int i = h[u]; ~i; i = e[i].next) {
            int v = e[i].to;
            if (e[i].cap > e[i].flow && dis[v] > dis[u] + e[i].cost) {
                dis[v] = dis[u] + e[i].cost;
                pre[v] = i;
                if (!inq[v]) {
                    inq[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return pre[t] != -1;
}

int mcmf(int s, int t, int &cost) {
    int flow = 0;
    cost = 0;
    while (spfa(s, t)) {
        int bottleneck = INF;
        for (int i = pre[t]; ~i; i = pre[e[i^1].to])
            bottleneck = min(bottleneck, e[i].cap - e[i].flow);
        for (int i = pre[t]; ~i; i = pre[e[i^1].to]) {
            e[i].flow += bottleneck;
            e[i^1].flow -= bottleneck;
            cost += e[i].cost * bottleneck;
        }
        flow += bottleneck;
    }
    return flow;
}

int encode(int x, int y) { return (x-1)*50 + y; }

int main() {
    int src = 101*55, dst = src + 1;
    n = read(), m = read(), k = read(), c = read(), d = read();
    int val;
    init(dst + 1);
    for (int i = 1; i <= k; i++) {
        val = read();
        link(src, val, 1, 0);
    }
    for (int col = 1; col <= 50; col++) {
        for (int row = 1; row <= 103; row++) {
            int u = encode(row, col), v = encode(row+1, col);
            link(u, v, INF, c);
        }
    }
    for (int i = 0; i < 102; i++) {
        int node = i*50 + 1;
        link(node, dst, INF, 0);
    }
    for (int i = 1; i <= m; i++) {
        int u = read(), v = read();
        for (int row = 1; row <= 102; row++) {
            int a = encode(row, u), a1 = encode(row+1, u);
            int b1 = encode(row+1, v), b = encode(row, v);
            for (int layer = 0; layer < 50; layer++) {
                int cost = d*(layer*2+1) + c;
                link(a, b1, 1, cost);
                link(b, a1, 1, cost);
            }
        }
    }
    int total_cost = 0;
    mcmf(src, dst, total_cost);
    cout << total_cost << endl;
    return 0;
}
